    cleaned_sex[cleaned_sex %in% c(-999, -998, -997, -995, -99)] <- -3
    cleaned_sex[cleaned_sex %in% c(-92, -9)] <- -9
    cleaned_sex[cleaned_sex %in% c(-91, -1, -8)] <- -1

    sex_vars[[var_name]] <- cleaned_sex
  } else {
    # If variable doesn't exist or file failed to load, create column of -3
    sex_vars[[var_name]] <- rep(-3, nrow(df))
  }
}

# Merge all data frames by NSID
merged_data <- reduce(sex_dfs, full_join, by = 'NSID')

# Create a data frame with all sex variables
sex_df <- as.data.frame(lapply(sex_vars, function(x) {
  if (length(x) == nrow(merged_data)) {
    x
  } else {
    rep(-3, nrow(merged_data))
  }
}))

# Determine most recent valid sex value
consolidated_sex <- apply(sex_df, 1, function(x) {
  valid_values <- x[!is.na(x) & x != -3 & x != -9 & x != -1]
  if (length(valid_values) > 0) {
    return(max(valid_values, na.rm = TRUE))
  } else {
    return(-3)
  }
})

# Create final output
final_data <- merged_data %>%
  select(NSID) %>%
  mutate(sex = factor(consolidated_sex,
                     levels = c(-3, -9, -1, 1, 2),
                     labels = c('Missing', 'Refused', 'Not applicable', 'Male', 'Female')))

# Write output
write_csv(final_data, 'data/output/cleaned_data.csv')
