# Load only NSID and sex variables from each file
load_sex_data <- function(file_info) {
  tryCatch({
    data <- read_delim(paste0('data/input/', file_info$file), delim = '\\t')
    # Select only NSID and the sex variable
    data %>% select(NSID, all_of(file_info$var))
  }, error = function(e) {
    NULL
  })
}

# Load each file individually
sex_dfs <- map(files_info, load_sex_data)

# Filter out NULL files (failed to load)
sex_dfs <- compact(sex_dfs)

# Create a base data frame with just NSID from the first file
base_data <- sex_dfs[[1]] %>% select(NSID)

# Create a list to store cleaned sex variables
sex_vars <- list()

# Process each file
for (i in seq_along(sex_dfs)) {
  df <- sex_dfs[[i]]
  var_name <- files_info[[i]]$var

  if (!is.null(df) && var_name %in% names(df)) {
    # Clean the sex variable
    cleaned_sex <- df[[var_name]]

    # Handle missing values according to standard scheme
    cleaned_sex[is.na(cleaned_sex)] <- -3
    cleaned_sex[cleaned_sex %in% c(-999, -998, -997, -995, -99)] <- -3
    cleaned_sex[cleaned_sex %in% c(-92, -9)] <- -9
    cleaned_sex[cleaned_sex %in% c(-91, -1, -8)] <- -1

    sex_vars[[var_name]] <- cleaned_sex
  } else {
    # If variable doesn't exist or file failed to load, create column of -3
    sex_vars[[var_name]] <- rep(-3, nrow(base_data))
  }
}

